#include "audio/ProductionAudioCueSystem.h"
#include <algorithm>
namespace subspace { ProductionAudioCue ProductionAudioCueSystem::ForVector(VectorTravelStage s,double p) const {p=std::clamp(p,0.0,1.0);switch(s){case VectorTravelStage::Charging:return{"vector_charge",float(.55+.35*p),float(.86+.28*p),true};case VectorTravelStage::Cruise:return{"vector_cruise",.82f,1.0f,true};case VectorTravelStage::Decelerating:return{"vector_exit",float(.78-.25*p),float(1.08-.16*p),false};default:return{};}} ProductionAudioCue ProductionAudioCueSystem::ForDocking(DockingExperienceStage s) const {switch(s){case DockingExperienceStage::Requested:return{"dock_clearance",.72f,1,false};case DockingExperienceStage::Capture:return{"dock_capture",.88f,.92f,false};case DockingExperienceStage::Docked:return{"dock_clamp",.84f,.86f,false};case DockingExperienceStage::Undocking:return{"dock_release",.78f,1.05f,false};default:return{};}} ProductionAudioCue ProductionAudioCueSystem::ForThruster(float t,bool reverse) const {t=std::clamp(t,0.0f,1.0f);return{reverse?"retro_thruster":"main_thruster",.22f+.68f*t,.82f+.22f*t,true};} }
